//! Embed everything the compiler needs, so the binary depends on nothing.
//!
//! Three wasm artifacts, two slot maps, and flint's standard library already
//! READ by the compiler being embedded (`DECISIONS.md#stdlib-preread`) -- its
//! forms, not its text.
//! They are GENERATED by `bin/build-dist`, not tracked, so this fails with a
//! sentence rather than with a missing-file error from `include_bytes!`.
use std::{env, fs, path::Path};

fn main() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf();
    let dist = root.join("dist");
    // The compiler as BYTECODE rather than as a module: this binary runs it
    // natively and has no wasm engine to run a module in. The format is an
    // implementation detail, embedded and never written out.
    for f in ["flintc.bytecode", "flint-runtime.wasm", "flint-runtime-aot.wasm",
              "slots.json", "slots-aot.json"] {
        if !dist.join(f).exists() {
            panic!("dist/{f} is missing. It is generated: run `bin/build-dist` first.");
        }
    }
    println!("cargo:rerun-if-changed={}", dist.display());
    println!("cargo:rerun-if-changed={}", root.join("lib").display());

    // The standard library, as (path, source) pairs, which are READ below and
    // not embedded. Every program needs it and a user should not have to carry
    // it.
    let lib = root.join("lib");
    let mut entries: Vec<(String, String)> = Vec::new();
    fn walk(dir: &Path, prefix: &str, out: &mut Vec<(String, String)>) {
        let mut names: Vec<_> = fs::read_dir(dir).unwrap().filter_map(|e| e.ok()).collect();
        names.sort_by_key(|e| e.path());
        for e in names {
            let p = e.path();
            let name = p.file_name().unwrap().to_string_lossy().to_string();
            let rel = if prefix.is_empty() { name.clone() } else { format!("{prefix}/{name}") };
            if p.is_dir() {
                walk(&p, &rel, out);
            // `flint.compiler.resolve/source-extensions` is the list that decides which
            // file WINS for a namespace; this one only decides what is worth
            // embedding, so a superset costs a read and a SUBSET loses a file
            // silently. `.fln` was missing here after the extension landed
            // everywhere else, which would have made a stdlib namespace moved
            // to `.fln` simply vanish from the binary.
            } else if rel.ends_with(".fln") || rel.ends_with(".cljc") || rel.ends_with(".clj") {
                out.push((rel, fs::read_to_string(&p).unwrap()));
            }
        }
    }
    walk(&lib, "", &mut entries);

    // The stdlib's OWN `deps.edn`, which names its workspace and says what it
    // holds. `walk` takes only `.cljc`/`.clj`, so without this the binary has
    // the standard library's code and no idea whose it is -- and a guard that
    // cannot name a workspace is a guard that never fires.
    let lib_deps = fs::read_to_string(lib.join("deps.edn")).unwrap_or_default();
    let mut src = format!("pub static STDLIB_DEPS: &str = {:?};\n", lib_deps);

    // `flint.deps`'s OWN workspace, separate from the blanket one above
    // (`DECISIONS.md#flint-deps-is-its-own-workspace`). A second embedded
    // `deps.edn` rather than a second copy of its contents, for the reason
    // the first one is embedded rather than hand-copied.
    let deps_ws_deps = fs::read_to_string(lib.join("flint/deps/deps.edn")).unwrap_or_default();
    src.push_str(&format!("pub static DEPS_WORKSPACE_DEPS: &str = {:?};\n", deps_ws_deps));

    // THE STANDARD LIBRARY, ALREADY READ, and not as text at all
    // (`DECISIONS.md#stdlib-preread`): read by the compiler this binary embeds,
    // so the forms are the ones that compiler would have read at run time and
    // there is no second reader to drift. ONE read serves every feature set --
    // the reader keeps `#?` as data and each compile resolves it -- and each
    // file is `flint.compiler.forms`'s compact encoding, decoded by the guest only when
    // a compile reaches its namespace.
    let out = Path::new(&env::var("OUT_DIR").unwrap()).to_path_buf();
    let bytecode = fs::read(dist.join("flintc.bytecode")).unwrap();
    let (blob, index) = preread(&bytecode, &entries);
    fs::write(out.join("stdlib.forms"), &blob).unwrap();
    src.push_str("pub static STDLIB_FORMS: &[u8] = include_bytes!(concat!(env!(\"OUT_DIR\"), \"/stdlib.forms\"));\n");
    src.push_str("pub static STDLIB_INDEX: &[(&str, usize, usize)] = &[\n");
    for (path, a, b) in &index {
        src.push_str(&format!("  ({path:?}, {a}, {b}),\n"));
    }
    src.push_str("];\n");
    fs::write(out.join("stdlib.rs"), src).unwrap();
    let text: usize = entries.iter().map(|e| e.1.len()).sum();
    println!("cargo:warning=pre-read {} standard-library files: {} bytes of forms from {} bytes of text",
             entries.len(), blob.len(), text);
}

/// Run the embedded compiler's `preread` mode over `entries` and answer one
/// blob holding each file's `flint.compiler.forms` bytes back to back, with an index of
/// where each starts and ends, sorted by path.
fn preread(bytecode: &[u8], entries: &[(String, String)]) -> (Vec<u8>, Vec<(String, usize, usize)>) {
    use flint_rt::codec::{parse, Val, Wire};
    let mut p = flint_rt::native::Program::load_with(bytecode, 3_000_000_000,
                                                             flint_conc::HOST_CATALOGUE)
        .unwrap_or_else(|e| panic!("the compiler in dist/ did not load to pre-read lib/: {e}"));
    let files = Val::Map(entries.iter()
        .map(|(k, v)| (Val::Str(k.clone()), Val::Str(v.clone()))).collect());
    let call = Val::Vector(vec![
        Val::Str("flint.compiler.selfhost/main".into()),
        Val::Vector(vec![Val::Str("split".into()), files, Val::Str("preread".into()),
                         Val::Str("{:files {}}".into())]),
    ]);
    let mut w = Wire::new();
    call.write(&mut w);
    let bytes = p.call(&w.done())
        .unwrap_or_else(|e| panic!("pre-reading lib/ failed: {e}"));
    let Val::Map(read) = parse(&bytes).unwrap_or_else(|e| panic!("pre-read answer: {e}")) else {
        panic!("pre-reading lib/ answered something that is not a map");
    };
    let mut read: Vec<(String, Vec<u8>)> = read.into_iter().map(|(k, v)| match (k, v) {
        (Val::Str(path), Val::Bytes(b)) => (path, b),
        (k, _) => panic!("pre-reading lib/ answered something that is not bytes for {k:?}"),
    }).collect();
    read.sort();
    let mut blob = Vec::new();
    let mut index = Vec::new();
    for (path, b) in read {
        let a = blob.len();
        blob.extend_from_slice(&b);
        index.push((path, a, blob.len()));
    }
    (blob, index)
}
